import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { pluralize } from 'lib/utils/strings'
import { projectLogic } from 'scenes/projectLogic'

import { hogFlowsApplyUtmDefaultsCreate } from '../../generated/api'
import type { ApplyUtmDefaultsResponseApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsUtmDefaultsApplyLogicValues {
    currentProjectId: number | null // projectLogic
    applyResult: ApplyUtmDefaultsResponseApi | null
    applyResultLoading: boolean
    enableWhereOff: boolean
    isApplyDialogOpen: boolean
    isPreviewCurrent: boolean
    preview: ApplyUtmDefaultsResponseApi | null
    previewLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsUtmDefaultsApplyLogicActions {
    applyDefaults: () => any
    applyDefaultsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    applyDefaultsSuccess: (
        applyResult: ApplyUtmDefaultsResponseApi,
        payload?: any
    ) => {
        applyResult: ApplyUtmDefaultsResponseApi
        payload?: any
    }
    closeApplyDialog: () => {
        value: true
    }
    loadPreview: (_: void) => void
    loadPreviewFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPreviewSuccess: (
        preview: ApplyUtmDefaultsResponseApi,
        payload?: void
    ) => {
        preview: ApplyUtmDefaultsResponseApi
        payload?: void
    }
    openApplyDialog: () => {
        value: true
    }
    setEnableWhereOff: (enableWhereOff: boolean) => {
        enableWhereOff: boolean
    }
}

export type workflowsUtmDefaultsApplyLogicType = MakeLogicType<
    workflowsUtmDefaultsApplyLogicValues,
    workflowsUtmDefaultsApplyLogicActions
>

export const workflowsUtmDefaultsApplyLogic = kea<workflowsUtmDefaultsApplyLogicType>([
    path(['products', 'workflows', 'frontend', 'scenes', 'settings', 'workflowsUtmDefaultsApplyLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    actions({
        openApplyDialog: true,
        closeApplyDialog: true,
        setEnableWhereOff: (enableWhereOff: boolean) => ({ enableWhereOff }),
    }),
    reducers({
        isApplyDialogOpen: [
            false,
            {
                openApplyDialog: () => true,
                closeApplyDialog: () => false,
            },
        ],
        enableWhereOff: [
            false,
            {
                setEnableWhereOff: (_, { enableWhereOff }) => enableWhereOff,
                openApplyDialog: () => false,
            },
        ],
        // The loader keeps its last result when a reload fails, so a count only counts while it is current.
        isPreviewCurrent: [
            false,
            {
                loadPreview: () => false,
                loadPreviewSuccess: () => true,
            },
        ],
    }),
    loaders(({ values }) => ({
        preview: [
            null as ApplyUtmDefaultsResponseApi | null,
            {
                loadPreview: async (_: void, breakpoint) => {
                    const preview = await hogFlowsApplyUtmDefaultsCreate(String(values.currentProjectId), {
                        dry_run: true,
                        enable_where_off: values.enableWhereOff,
                    })
                    // A reopened dialog or a toggled box starts a newer preview, so this count is stale.
                    breakpoint()
                    return preview
                },
            },
        ],
        applyResult: [
            null as ApplyUtmDefaultsResponseApi | null,
            {
                applyDefaults: async () => {
                    return await hogFlowsApplyUtmDefaultsCreate(String(values.currentProjectId), {
                        dry_run: false,
                        enable_where_off: values.enableWhereOff,
                    })
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        openApplyDialog: () => actions.loadPreview(),
        setEnableWhereOff: () => actions.loadPreview(),
        applyDefaultsSuccess: ({ applyResult }) => {
            actions.closeApplyDialog()
            const skipped = (applyResult?.workflows_failed ?? 0) + (applyResult?.workflows_without_access ?? 0)
            if (skipped > 0) {
                lemonToast.warning(
                    `Updated ${pluralize(applyResult?.emails_updated ?? 0, 'email')}. ${pluralize(skipped, 'workflow')} kept their old values.`
                )
            } else {
                lemonToast.success(
                    `Updated ${pluralize(applyResult?.emails_updated ?? 0, 'email')} with the new defaults`
                )
            }
        },
        applyDefaultsFailure: () => {
            lemonToast.error("Couldn't update existing emails. Try again.")
        },
        loadPreviewFailure: () => {
            lemonToast.error("Couldn't count the emails to update. Try again.")
        },
    })),
])
